<?php
declare(strict_types=1);
namespace QualitySystem\Repositories;
use PDO;use QualitySystem\Domain\ProgramSpecification\ProgramSpecification;
final class ProgramSpecificationRepository
{
    public const EDITABLE=['study_plan_id','specification_title','program_name','program_code','qualification_level','department_name','college_name','institution_name','specification_version','academic_year','specification_type','last_review_date','previous_version_file','main_location','branches','partnerships','qualified_jobs','occupational_sectors','total_credit_hours','program_mission','program_goals','graduate_attributes','admission_requirements','graduation_requirements','guidance_orientation','counseling_services','special_support','teaching_learning_strategy','assessment_strategy','learning_resources','facilities_equipment','healthy_safe_environment','quality_assurance_arrangements','quality_assurance_system','quality_manual_reference','quality_courses_other_departments','consistency_between_sections','plo_assessment_plan','plo_assessment_plan_reference','approval_council_committee','approval_reference_no','approval_date_text','approval_date','approval_status','status','notes'];
    private const LINKED=['program_specification_plos','program_specification_courses','program_specification_plo_course_mapping','program_specification_kpis','program_specification_curriculum_structure','program_specification_teaching_strategies','program_specification_assessment_methods','program_specification_mark_distributions','program_specification_staffing_needs','program_specification_evaluation_matrix','program_specification_tracks','program_specification_exit_points'];
    public function __construct(private readonly PDO $pdo){}
    private function scope(string $role,int $userId,array &$params,string $alias='ps'):string{if(in_array($role,['Admin','Quality Coordinator'],true))return'1=1';$params[':program_scope_user']=$userId;return"$alias.id IN (SELECT program_specification_id FROM user_program_access WHERE user_id=:program_scope_user)";}
    public function paginate(string $role,int $userId,int $page,int $perPage,array $filters):array{$params=[];$where=$this->scope($role,$userId,$params);if($filters['search']!==''){$where.=' AND (ps.specification_title LIKE :search OR ps.program_name LIKE :search OR ps.program_code LIKE :search)';$params[':search']='%'.$filters['search'].'%';}foreach(['approval_status','specification_type'] as $field)if($filters[$field]!==''){$where.=" AND ps.$field=:$field";$params[":$field"]=$filters[$field];}$count=$this->pdo->prepare("SELECT COUNT(*) FROM program_specifications ps WHERE $where");$count->execute($params);$sql="SELECT ps.*,sp.plan_title study_plan_title,(SELECT COUNT(*) FROM program_specification_plos x WHERE x.program_specification_id=ps.id) plo_count,(SELECT COUNT(*) FROM program_specification_courses x WHERE x.program_specification_id=ps.id) course_count,(SELECT COUNT(*) FROM program_specification_kpis x WHERE x.program_specification_id=ps.id) kpi_count FROM program_specifications ps LEFT JOIN study_plans sp ON sp.id=ps.study_plan_id WHERE $where ORDER BY FIELD(ps.approval_status,'Approved','Under Review','Draft','Archived'),ps.id DESC LIMIT :limit OFFSET :offset";$s=$this->pdo->prepare($sql);foreach($params as $key=>$value)$s->bindValue($key,$value);$s->bindValue(':limit',$perPage,PDO::PARAM_INT);$s->bindValue(':offset',($page-1)*$perPage,PDO::PARAM_INT);$s->execute();return['rows'=>$s->fetchAll(PDO::FETCH_ASSOC),'total'=>(int)$count->fetchColumn()];}
    public function findScoped(int $id,string $role,int $userId):?array{$params=[':id'=>$id];$scope=$this->scope($role,$userId,$params);$s=$this->pdo->prepare("SELECT * FROM program_specifications ps WHERE ps.id=:id AND $scope LIMIT 1");$s->execute($params);return$s->fetch(PDO::FETCH_ASSOC)?:null;}
    public function save(ProgramSpecification $spec):int{$fields=array_intersect_key($spec->fields,array_flip(self::EDITABLE));$assign=[];$params=[];foreach($fields as $column=>$value){$assign[]="`$column`=:$column";$params[":$column"]=$value;}if($spec->id===null){$sql='INSERT INTO program_specifications SET '.implode(',',$assign);$this->pdo->prepare($sql)->execute($params);return(int)$this->pdo->lastInsertId();}$params[':id']=$spec->id;$sql='UPDATE program_specifications SET '.implode(',',$assign).' WHERE id=:id';$this->pdo->prepare($sql)->execute($params);return$spec->id;}
    public function linkedCounts(int $id):array{$counts=[];foreach(self::LINKED as $table){$s=$this->pdo->prepare("SELECT COUNT(*) FROM `$table` WHERE program_specification_id=:id");$s->execute([':id'=>$id]);$count=(int)$s->fetchColumn();if($count)$counts[$table]=$count;}return$counts;}
    public function delete(int $id):void{$this->pdo->prepare('DELETE FROM program_specifications WHERE id=:id')->execute([':id'=>$id]);}
    public function studyPlans():array{return$this->pdo->query('SELECT id,plan_title,program_name FROM study_plans ORDER BY id DESC LIMIT 500')->fetchAll(PDO::FETCH_ASSOC);}
}
